// Same as the thingProperties.h generated by Arduino Cloud,
// except that the Device ID is moved to credentials.h.

#include <ArduinoIoTCloud.h>
#include <Arduino_ConnectionHandler.h>

const char DEVICE_LOGIN_NAME[] = SECRET_DEVICE_ID;  // Device ID

const char SSID[] = SECRET_SSID;                // Wi-Fi SSID
const char PASS[] = SECRET_OPTIONAL_PASS;       // Wi-Fi password
const char DEVICE_KEY[] = SECRET_DEVICE_KEY;    // Secret Key

void onRedChange();
void onGreenChange();
void onBlueChange();
void onBrightnessChange();

int red;
int green;
int blue;
int brightness;

void initProperties() {
  ArduinoCloud.setBoardId(DEVICE_LOGIN_NAME);
  ArduinoCloud.setSecretDeviceKey(DEVICE_KEY);
  ArduinoCloud.addProperty(red, READWRITE, ON_CHANGE, onRedChange);
  ArduinoCloud.addProperty(green, READWRITE, ON_CHANGE, onGreenChange);
  ArduinoCloud.addProperty(blue, READWRITE, ON_CHANGE, onBlueChange);
  ArduinoCloud.addProperty(brightness, READWRITE, ON_CHANGE, onBrightnessChange);
}

WiFiConnectionHandler ArduinoIoTPreferredConnection(SSID, PASS);
